"""Convenience helpers for PyUSB using UniTool's authorized USB bridge."""
import os


def get_backend():
    """Return PyUSB's libusb1 backend bound to UniTool's packaged libusb.so."""
    library_path = (
        os.environ.get("UNITOOL_LIBUSB_PATH")
        or os.environ.get("PYUSB_LIBUSB_PATH")
    )
    if not library_path:
        raise RuntimeError("UNITOOL_LIBUSB_PATH is not configured")

    library_path = os.path.abspath(library_path)
    if not os.path.isfile(library_path):
        raise FileNotFoundError(
            "UniTool's broker-backed libusb library is missing: " + library_path
        )

    try:
        from usb.backend import libusb1
    except ImportError as exc:
        raise RuntimeError(
            "PyUSB is not installed. Install it with: python -m pip install pyusb"
        ) from exc

    backend = libusb1.get_backend(
        find_library=lambda _name: library_path
    )
    if backend is None:
        raise RuntimeError(
            "PyUSB could not load UniTool's broker-backed libusb: " + library_path
        )
    return backend


def find_all(**kwargs):
    """Enumerate devices through UniTool's UsbManager-authorized broker."""
    from usb.core import find

    kwargs["find_all"] = True
    kwargs["backend"] = get_backend()
    return find(**kwargs)
